-- Robotics/Embedded/IoT pathway ("Vector Division") Act 3 -- "Binary
-- Machines" content, world id world-vec-binary-machines (already created
-- in 20260813070000_robotics_acts2_5_spine.sql). 1 campaign, 2
-- operations, 12 missions (11 lessons + boss), following the same
-- campaigns -> operations -> missions -> dialogue -> objectives ->
-- challenges -> hints pattern as every other pathway/Act. No new
-- ChallengeType needed -- reuses story_dialogue, investigation,
-- multiple_choice, interactive_diagram, drag_and_drop, browser_simulation
-- (generic console fallback) and boss_encounter.
--
-- Narrative thread: Tomas Vey pulls a raw register dump off the door
-- controller board recovered in Act 1 and studied electrically on the
-- bench in Act 2. This Act teaches the vocabulary to read that dump --
-- binary/hex, bits/bytes/words, Boolean logic and its four operators,
-- truth tables, bitwise operations, registers, memory-mapped I/O,
-- endianness, signed integers and fixed-width overflow -- and closes with
-- the boss mission proving that a value recurring across the dump,
-- 0xDEAD, is not a fault code but an uninitialized placeholder the
-- original engineers never revisited, thirty years ago. SUBSTRATE does
-- not speak this Act; this is Tomas, Byte and Imani analyzing a dead,
-- recovered board.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-vec-binary-machines', 'world-vec-binary-machines', 'binary-machines', '1B - Binary Machines', 'Learn to read a board the way a machine does -- binary and hexadecimal, bits/bytes/words, Boolean logic, truth tables, bitwise operations, registers, memory-mapped I/O, endianness, signed integers and fixed-width overflow -- while Tomas Vey and Byte decode a raw register dump pulled off the recovered door controller.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-vec-binary-machines-1', 'campaign-vec-binary-machines', 'the-vocabulary-of-the-dump', 'The Vocabulary of the Dump', 'Binary and hexadecimal, bits, bytes and words, Boolean logic, AND OR NOT XOR, truth tables, and bitwise operations.', 1),
  ('operation-vec-binary-machines-2', 'campaign-vec-binary-machines', 'reading-the-registers', 'Reading the Registers', 'Registers, memory-mapped I/O intuition, endianness, signed integers, fixed-width overflow, and the value that will not stop repeating.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-vec-binary-machines-01', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-1', 'binary-and-hexadecimal', 'Binary and Hexadecimal', 'Tomas Vey pulls a raw register dump from the recovered board''s memory. Before any of it means something, it has to be read correctly -- starting with why hexadecimal is standing in for binary at all.', 'beginner', ARRAY['tomas','byte'], null, null, '{"type":"simulation","simulationId":"binary-and-hexadecimal-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 1),
  ('mission-vec-binary-machines-02', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-1', 'bits-bytes-and-words', 'Bits, Bytes and Words', 'This board''s registers are sixteen bits wide. Learning how bits, bytes and words nest inside each other is what turns four hex digits into one coherent value instead of four unrelated ones.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-binary-machines-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"bits-bytes-and-words-sim"}'::jsonb, '{"xp":100,"credits":20}'::jsonb, false, 2),
  ('mission-vec-binary-machines-03', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-1', 'boolean-logic', 'Boolean Logic', 'Every bit is already true or false in disguise. Boolean logic is the small set of rules for combining those values -- the foundation every gate on this board is built from.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-binary-machines-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"boolean-logic-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 3),
  ('mission-vec-binary-machines-04', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-1', 'and-or-not-xor', 'AND, OR, NOT, XOR', 'AND, OR, NOT and XOR are not abstractions. They are physical logic gates wired into the board''s silicon, and each one behaves in exactly one fixed way.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-binary-machines-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"and-or-not-xor-sim"}'::jsonb, '{"xp":110,"credits":20}'::jsonb, false, 4),
  ('mission-vec-binary-machines-05', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-1', 'truth-tables', 'Truth Tables', 'A truth table lists every input combination a gate can see and the output it produces for each -- the tool that lets you verify a gate''s behavior instead of memorizing it.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-binary-machines-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"truth-tables-sim"}'::jsonb, '{"xp":120,"credits":20}'::jsonb, false, 5),
  ('mission-vec-binary-machines-06', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-1', 'bitwise-operations', 'Bitwise Operations', 'Applied across a whole register instead of one bit at a time, AND, OR, NOT and XOR become bitwise operations -- powerful enough to isolate a single flag out of a packed status byte.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-binary-machines-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"bitwise-operations-sim"}'::jsonb, '{"xp":120,"credits":25}'::jsonb, false, 6),
  ('mission-vec-binary-machines-07', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-2', 'registers', 'Registers', 'A register is a fixed-width, named, addressed storage location inside the board. Laid out as a table instead of a wall of hex, something in this board''s registers stops looking ordinary.', 'beginner', ARRAY['tomas','byte'], '{"requiredMissionIds":["mission-vec-binary-machines-06"]}'::jsonb, null, '{"type":"simulation","simulationId":"registers-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 7),
  ('mission-vec-binary-machines-08', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-2', 'memory-mapped-io', 'Memory-Mapped I/O', 'Registers are not hidden behind a special protocol. They sit at ordinary memory addresses, memory-mapped, which is exactly why last Act''s diagnostic console could read them at all.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-binary-machines-07"]}'::jsonb, null, '{"type":"simulation","simulationId":"memory-mapped-io-sim"}'::jsonb, '{"xp":130,"credits":25}'::jsonb, false, 8),
  ('mission-vec-binary-machines-09', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-2', 'endianness', 'Endianness', 'A sixteen-bit value is really two bytes traveling in some order. Endianness is the rule for which byte comes first -- get it backward, and every multi-byte value on the bus comes out scrambled.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-binary-machines-08"]}'::jsonb, null, '{"type":"simulation","simulationId":"endianness-sim"}'::jsonb, '{"xp":140,"credits":25}'::jsonb, false, 9),
  ('mission-vec-binary-machines-10', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-2', 'signed-integers', 'Signed Integers', 'Not every register value is unsigned. Signed integers reserve the top bit to mean negative, using two''s complement -- worth ruling in or out before calling any value a mistake.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-vec-binary-machines-09"]}'::jsonb, null, '{"type":"simulation","simulationId":"signed-integers-sim"}'::jsonb, '{"xp":140,"credits":30}'::jsonb, false, 10),
  ('mission-vec-binary-machines-11', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-2', 'fixed-width-overflow', 'Fixed-Width Overflow', 'Every fixed-width register has a ceiling. Overflow is what happens when a value tries to cross it -- and the artifacts it leaves behind land in a very specific, very recognizable place.', 'beginner', ARRAY['byte','tomas'], '{"requiredMissionIds":["mission-vec-binary-machines-10"]}'::jsonb, null, '{"type":"simulation","simulationId":"fixed-width-overflow-sim"}'::jsonb, '{"xp":150,"credits":30}'::jsonb, false, 11),
  ('mission-vec-binary-machines-12', 'world-vec-binary-machines', 'campaign-vec-binary-machines', 'operation-vec-binary-machines-2', '0xdead', '0xDEAD', 'Every tool this Act taught, aimed at one recurring value. Not a guess -- a proof, built the same way Vector Division proves anything: rule out the ordinary explanations first.', 'boss', ARRAY['imani','tomas','byte'], '{"requiredMissionIds":["mission-vec-binary-machines-11"]}'::jsonb, null, '{"type":"simulation","simulationId":"0xdead-sim"}'::jsonb, '{"xp":460,"credits":100,"badgeIds":["the-placeholder-value"],"skillXp":{"robotics_fundamentals":65}}'::jsonb, true, 12);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-vec-binary-machines-01', 1, 'tomas', 'I pulled a full register dump off the board''s memory last night. Every value in it is either binary or hex, and neither one means anything until you have the vocabulary to read it.'),
  ('mission-vec-binary-machines-01', 2, 'byte', 'Binary is the truth of it -- every register on that board is really just a row of ones and zeros. Hexadecimal is not a different kind of number. It is a compact stand-in for binary, because nobody wants to read sixteen digits of ones and zeros when four hex digits say the exact same thing.'),
  ('mission-vec-binary-machines-01', 3, 'tomas', 'Each hex digit covers exactly four binary digits. Learn that one conversion and the whole dump stops looking like static.'),
  ('mission-vec-binary-machines-01', 4, 'byte', 'Let us start with the very first value in the dump. Translate it, and do not worry yet about what it means. Meaning comes later. Right now I just want you reading it correctly.'),

  ('mission-vec-binary-machines-02', 1, 'byte', 'A bit is the smallest unit there is -- one binary digit, either 0 or 1. Group eight of them together and you get a byte. Group two bytes together and, on a board like this one, you get a word.'),
  ('mission-vec-binary-machines-02', 2, 'byte', 'This board''s registers are all sixteen bits wide. That means every register value you saw in the dump, including that first one, is exactly one word -- two bytes, four hex digits, no more and no less.'),
  ('mission-vec-binary-machines-02', 3, 'tomas', 'So when you see a value like 0xDEAD sitting in a register, that is not four independent digits. It is one complete word, occupying the whole register at once.'),

  ('mission-vec-binary-machines-03', 1, 'byte', 'Every bit is already a Boolean value in disguise. 1 means true, 0 means false. Boolean logic is just the set of rules for combining true and false values to get a new true or false value.'),
  ('mission-vec-binary-machines-03', 2, 'byte', 'It sounds almost too simple to matter. It is the entire foundation every digital circuit on that board is built from.'),

  ('mission-vec-binary-machines-04', 1, 'byte', 'Four operators do almost all the work. AND is true only if both inputs are true. OR is true if at least one input is true. NOT simply flips a single value. XOR -- exclusive or -- is true only if the inputs differ from each other.'),
  ('mission-vec-binary-machines-04', 2, 'tomas', 'Every one of those shows up on this board as an actual logic gate, wired in silicon. They are not abstractions. They are physical circuits.'),

  ('mission-vec-binary-machines-05', 1, 'byte', 'A truth table just lists every possible combination of inputs and the output each one produces. For a two-input operator there are only four rows -- 00, 01, 10, 11.'),
  ('mission-vec-binary-machines-05', 2, 'byte', 'Once you know how to build one, you can verify any claim about AND, OR, NOT or XOR yourself, instead of trusting me to recite it.'),

  ('mission-vec-binary-machines-06', 1, 'byte', 'Bitwise operations apply AND, OR, NOT or XOR to every matching bit position in two full values at once, not just to a single 0 or 1.'),
  ('mission-vec-binary-machines-06', 2, 'tomas', 'That matters here because a single register value like a status byte can pack several unrelated flags into one word. A bitwise AND with the right mask isolates exactly one flag and ignores the rest.'),
  ('mission-vec-binary-machines-06', 3, 'byte', 'It is called masking. Line the mask up so it has 1s exactly where you want to look, and 0s everywhere else.'),

  ('mission-vec-binary-machines-07', 1, 'tomas', 'A register is a small, named storage location inside the board, fixed at a specific width, sitting at a specific address. This board gives every one of them a label -- STATUS_MAIN, CHANNEL_A_CAL, and so on.'),
  ('mission-vec-binary-machines-07', 2, 'byte', 'I laid out the first several registers from the dump by address and label. Something in here is going to look wrong once you actually read it as a table instead of a wall of hex.'),
  ('mission-vec-binary-machines-07', 3, 'tomas', 'Read the whole table before you decide what is wrong.'),

  ('mission-vec-binary-machines-08', 1, 'byte', 'Memory-mapped I/O means the board''s registers are not tucked away behind some special instruction. They sit at ordinary memory addresses, right alongside everything else, so reading or writing a register looks exactly like reading or writing memory.'),
  ('mission-vec-binary-machines-08', 2, 'tomas', 'That is exactly why Byte''s diagnostic console from Act 1 could read this dump at all. It never needed a special protocol. It just read memory at known addresses.'),
  ('mission-vec-binary-machines-08', 3, 'byte', 'Which also means the register addresses are not arbitrary. Whoever designed this board picked exactly where CHANNEL_A_CAL and CHANNEL_B_CAL would live, and placed them right next to each other on purpose.'),

  ('mission-vec-binary-machines-09', 1, 'byte', 'A sixteen-bit register value is really two separate bytes. Endianness is just the rule for which byte comes first when they travel over a bus one at a time -- big-endian sends the high byte first, little-endian sends the low byte first.'),
  ('mission-vec-binary-machines-09', 2, 'tomas', 'This board''s maintenance bus is documented as little-endian. Get that rule backward and every multi-byte value you read off it comes out scrambled.'),
  ('mission-vec-binary-machines-09', 3, 'byte', 'Two raw bytes just came off the bus for one of the calibration registers. Read them correctly, and do not assume.'),

  ('mission-vec-binary-machines-10', 1, 'byte', 'So far every value has been unsigned -- just a magnitude, nothing negative allowed. Signed integers reserve one bit, the most significant bit, to mean negative instead of adding it to the magnitude.'),
  ('mission-vec-binary-machines-10', 2, 'byte', 'The standard scheme is two''s complement. If the top bit is 0, read the rest as an ordinary positive number. If the top bit is 1, the value is negative, and you get its magnitude by inverting every bit and adding one.'),
  ('mission-vec-binary-machines-10', 3, 'tomas', 'Worth checking, because a calibration register with its top bit set might just be a legitimate negative offset, not a mistake.'),

  ('mission-vec-binary-machines-11', 1, 'byte', 'Every register only has so many bits. A sixteen-bit register can hold exactly 65,536 distinct values, from 0x0000 to 0xFFFF, and nothing outside that range.'),
  ('mission-vec-binary-machines-11', 2, 'byte', 'Overflow happens when a calculation tries to produce a value outside that range. The extra bit does not go anywhere -- it is simply dropped, and the value silently wraps back around to the bottom.'),
  ('mission-vec-binary-machines-11', 3, 'tomas', '0xFFFF plus one does not become 0x10000. On this board it becomes 0x0000, as if nothing ever happened. Keep that in mind before you blame every strange value on overflow.'),

  ('mission-vec-binary-machines-12', 1, 'imani', 'Walk me through it. Tomas says the dump is not garbage, it is a real finding. Prove it, in the vocabulary you just spent this whole Act learning.'),
  ('mission-vec-binary-machines-12', 2, 'tomas', 'Do not just tell me the number looks strange. Rule out every ordinary explanation first, the way you would for any other reading.'),
  ('mission-vec-binary-machines-12', 3, 'byte', 'I have the full register table, the raw bus capture, and the board''s documented status and fault code list all pulled up. Everything you need is already in front of you.'),
  ('mission-vec-binary-machines-12', 4, 'imani', 'Then tell me what 0xDEAD actually is, and what that tells us about the day this board went into the wall.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-vec-binary-machines-01-o1', 'mission-vec-binary-machines-01', 1, 'Open the Dump', 'Understand why the register dump is written in hexadecimal even though the board only ever stores binary.'),
  ('mission-vec-binary-machines-01-o2', 'mission-vec-binary-machines-01', 2, 'Translate the First Value', 'Convert the dump''s first raw register value into hexadecimal.'),

  ('mission-vec-binary-machines-02-o1', 'mission-vec-binary-machines-02', 1, 'Define the Units', 'State how bits, bytes and words relate to each other in size.'),
  ('mission-vec-binary-machines-02-o2', 'mission-vec-binary-machines-02', 2, 'Size the Register', 'Work out how many bytes a single 16-bit register value like 0xDEAD actually occupies.'),

  ('mission-vec-binary-machines-03-o1', 'mission-vec-binary-machines-03', 1, 'Define Boolean Logic', 'State what Boolean logic actually operates on.'),
  ('mission-vec-binary-machines-03-o2', 'mission-vec-binary-machines-03', 2, 'Sort the Values', 'Sort each example into true or false.'),

  ('mission-vec-binary-machines-04-o1', 'mission-vec-binary-machines-04', 1, 'Match Operator to Behavior', 'Match each operator to its correct description.'),
  ('mission-vec-binary-machines-04-o2', 'mission-vec-binary-machines-04', 2, 'Evaluate an Expression', 'Compute the result of a specific operator applied to two bit values.'),

  ('mission-vec-binary-machines-05-o1', 'mission-vec-binary-machines-05', 1, 'Build the Table', 'Order the four input combinations a two-input truth table must cover, from first to last.'),
  ('mission-vec-binary-machines-05-o2', 'mission-vec-binary-machines-05', 2, 'Read the Table', 'Use a completed truth table to answer a specific case.'),

  ('mission-vec-binary-machines-06-o1', 'mission-vec-binary-machines-06', 1, 'Apply a Bitwise AND', 'Compute a bitwise AND between two 8-bit values.'),
  ('mission-vec-binary-machines-06-o2', 'mission-vec-binary-machines-06', 2, 'Isolate a Flag', 'Use a bitmask to isolate one status flag from a packed register byte.'),

  ('mission-vec-binary-machines-07-o1', 'mission-vec-binary-machines-07', 1, 'Define a Register', 'State what a register actually is.'),
  ('mission-vec-binary-machines-07-o2', 'mission-vec-binary-machines-07', 2, 'Spot the Repeat', 'Find the value that recurs across multiple unrelated registers in the table.'),

  ('mission-vec-binary-machines-08-o1', 'mission-vec-binary-machines-08', 1, 'Define Memory-Mapped I/O', 'State what it means for a register to be memory-mapped.'),
  ('mission-vec-binary-machines-08-o2', 'mission-vec-binary-machines-08', 2, 'Order the Access Path', 'Order the steps of reading a memory-mapped register from address to value.'),

  ('mission-vec-binary-machines-09-o1', 'mission-vec-binary-machines-09', 1, 'Define Endianness', 'State the difference between big-endian and little-endian byte order.'),
  ('mission-vec-binary-machines-09-o2', 'mission-vec-binary-machines-09', 2, 'Read the Bus Correctly', 'Reconstruct the correct 16-bit value from two raw bytes given the bus''s documented endianness.'),

  ('mission-vec-binary-machines-10-o1', 'mission-vec-binary-machines-10', 1, 'Define Two''s Complement', 'State how two''s complement represents a negative number.'),
  ('mission-vec-binary-machines-10-o2', 'mission-vec-binary-machines-10', 2, 'Convert a Signed Value', 'Convert a specific 16-bit two''s complement value to its signed decimal equivalent.'),

  ('mission-vec-binary-machines-11-o1', 'mission-vec-binary-machines-11', 1, 'Define Overflow', 'State what happens when a fixed-width register overflows.'),
  ('mission-vec-binary-machines-11-o2', 'mission-vec-binary-machines-11', 2, 'Judge the Boundary', 'Decide whether a specific register value could plausibly be an overflow artifact.'),

  ('mission-vec-binary-machines-12-o1', 'mission-vec-binary-machines-12', 1, 'Prove the Pattern', 'Show that 0xDEAD recurs across multiple, physically unrelated registers rather than appearing once.'),
  ('mission-vec-binary-machines-12-o2', 'mission-vec-binary-machines-12', 2, 'Rule Out a Misread', 'Prove that 0xDEAD is not simply a misread value in the wrong byte order.'),
  ('mission-vec-binary-machines-12-o3', 'mission-vec-binary-machines-12', 3, 'Rule Out Real Data', 'Prove that 0xDEAD is not a legitimate overflow artifact or a valid signed sensor reading.'),
  ('mission-vec-binary-machines-12-o4', 'mission-vec-binary-machines-12', 4, 'State the Finding', 'Having proven the pattern, ruled out a misread, and ruled out real data, state what 0xDEAD actually is and what it implies about how this board was originally commissioned.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-vec-binary-machines-01-o1-c1', 'mission-vec-binary-machines-01-o1', 1, 'investigation', 'Which piece of evidence explains why engineers write register dumps in hexadecimal instead of raw binary?', '{"evidence":[{"id":"e1","label":"Byte''s note","detail":"Hexadecimal numbers use 16 symbols (0-9, A-F); binary uses only two (0, 1)"},{"id":"e2","label":"Byte''s note","detail":"Each hex digit corresponds to exactly four binary digits, so hex is a direct shorthand for binary, not a separate numbering system"},{"id":"e3","label":"Tomas''s note","detail":"The dump was exported straight from the board''s memory controller with no translation applied"}],"question":"Which piece of evidence explains why engineers write register dumps in hexadecimal instead of raw binary?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),
  ('mission-vec-binary-machines-01-o2-c1', 'mission-vec-binary-machines-01-o2', 1, 'multiple_choice', 'The first value in the dump is the 16-bit pattern 1101 1110 1010 1101. Group it into four-bit chunks and convert each to hex. What is the value?', '{"question":"The first value in the dump is the 16-bit pattern 1101 1110 1010 1101. Group it into four-bit chunks and convert each to hex. What is the value?","options":[{"id":"a","text":"0xADDE"},{"id":"b","text":"0xDEAD"},{"id":"c","text":"0xDAEB"},{"id":"d","text":"0xEADD"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-binary-machines-02-o1-c1', 'mission-vec-binary-machines-02-o1', 1, 'multiple_choice', 'How do a bit, a byte and a word relate to each other on this board?', '{"question":"How do a bit, a byte and a word relate to each other on this board?","options":[{"id":"a","text":"A byte is 10 bits, and a word is 100 bits"},{"id":"b","text":"A bit is one binary digit; a byte is 8 bits; a word on this board is 16 bits, or 2 bytes"},{"id":"c","text":"They are three different names for the same thing"},{"id":"d","text":"A word is always exactly 4 bits"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-02-o2-c1', 'mission-vec-binary-machines-02-o2', 1, 'multiple_choice', 'The register value 0xDEAD has four hex digits. How does that map onto bytes in a 16-bit-wide register?', '{"question":"The register value 0xDEAD has four hex digits. How does that map onto bytes in a 16-bit-wide register?","options":[{"id":"a","text":"4 bytes, one per hex digit"},{"id":"b","text":"2 bytes -- 0xDE is the high byte and 0xAD is the low byte, together forming one 16-bit word"},{"id":"c","text":"1 byte, hex digits do not map to bytes"},{"id":"d","text":"8 bytes"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-binary-machines-03-o1-c1', 'mission-vec-binary-machines-03-o1', 1, 'multiple_choice', 'Boolean logic operates on...', '{"question":"Boolean logic operates on...","options":[{"id":"a","text":"Any number at all, positive or negative"},{"id":"b","text":"Exactly two values, true and false (equivalently 1 and 0), combined by fixed logical rules"},{"id":"c","text":"Only hexadecimal digits"},{"id":"d","text":"Text strings"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-03-o2-c1', 'mission-vec-binary-machines-03-o2', 1, 'drag_and_drop', 'Sort each example into true or false.', '{"items":[{"id":"i1","text":"A bit reading 1"},{"id":"i2","text":"A bit reading 0"},{"id":"i3","text":"A statement that is logically correct"},{"id":"i4","text":"A statement that is logically incorrect"}],"targets":[{"id":"true","label":"True"},{"id":"false","label":"False"}]}'::jsonb, '{"correctMapping":{"i1":"true","i2":"false","i3":"true","i4":"false"}}'::jsonb),

  ('mission-vec-binary-machines-04-o1-c1', 'mission-vec-binary-machines-04-o1', 1, 'drag_and_drop', 'Match each operator to its correct description.', '{"items":[{"id":"i1","text":"Requires both inputs to be true"},{"id":"i2","text":"Requires at least one input to be true"},{"id":"i3","text":"Flips a single input"},{"id":"i4","text":"True only when the two inputs differ"}],"targets":[{"id":"AND","label":"AND"},{"id":"OR","label":"OR"},{"id":"NOT","label":"NOT"},{"id":"XOR","label":"XOR"}]}'::jsonb, '{"correctMapping":{"i1":"AND","i2":"OR","i3":"NOT","i4":"XOR"}}'::jsonb),
  ('mission-vec-binary-machines-04-o2-c1', 'mission-vec-binary-machines-04-o2', 1, 'multiple_choice', 'What is 1 XOR 1?', '{"question":"What is 1 XOR 1?","options":[{"id":"a","text":"1"},{"id":"b","text":"0"},{"id":"c","text":"Undefined"},{"id":"d","text":"-1"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-binary-machines-05-o1-c1', 'mission-vec-binary-machines-05-o1', 1, 'interactive_diagram', 'Order the four input combinations a two-input truth table must cover, from first to last.', '{"diagramId":"truth-table-rows","hotspots":[{"id":"row00","label":"0, 0","explanation":"Both inputs false."},{"id":"row01","label":"0, 1","explanation":"First input false, second true."},{"id":"row10","label":"1, 0","explanation":"First input true, second false."},{"id":"row11","label":"1, 1","explanation":"Both inputs true."}],"task":"Order the rows from 00 to 11."}'::jsonb, '{"correctOrderIds":["row00","row01","row10","row11"]}'::jsonb),
  ('mission-vec-binary-machines-05-o2-c1', 'mission-vec-binary-machines-05-o2', 1, 'multiple_choice', 'According to AND''s truth table, what is the output when both inputs are 1?', '{"question":"According to AND''s truth table, what is the output when both inputs are 1?","options":[{"id":"a","text":"0"},{"id":"b","text":"1"},{"id":"c","text":"Depends on order"},{"id":"d","text":"Undefined"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-binary-machines-06-o1-c1', 'mission-vec-binary-machines-06-o1', 1, 'multiple_choice', 'What is 1100 1010 AND 0000 1111?', '{"question":"What is 1100 1010 AND 0000 1111?","options":[{"id":"a","text":"1100 0000"},{"id":"b","text":"0000 1010"},{"id":"c","text":"1100 1010"},{"id":"d","text":"1111 1111"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-06-o2-c1', 'mission-vec-binary-machines-06-o2', 1, 'investigation', 'Which piece of evidence explains how to isolate just the ONLINE flag from STATUS_MAIN without disturbing any other bit?', '{"evidence":[{"id":"e1","label":"Register byte","detail":"STATUS_MAIN reads 0000 0101"},{"id":"e2","label":"Mask note","detail":"Applying mask 0000 0001 with a bitwise AND isolates only the lowest bit, the ONLINE flag, and zeroes out every other bit"},{"id":"e3","label":"Tomas''s note","detail":"The board has 6 defined status flags total, packed across two bytes"}],"question":"Which piece of evidence explains how to isolate just the ONLINE flag from STATUS_MAIN without disturbing any other bit?"}'::jsonb, '{"requiredEvidenceIds":["e2"]}'::jsonb),

  ('mission-vec-binary-machines-07-o1-c1', 'mission-vec-binary-machines-07-o1', 1, 'multiple_choice', 'A register is best described as...', '{"question":"A register is best described as...","options":[{"id":"a","text":"A temporary file stored on disk"},{"id":"b","text":"A fixed-width, named storage location at a specific address inside the board, holding one value at a time"},{"id":"c","text":"A type of logic gate"},{"id":"d","text":"A network protocol"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-07-o2-c1', 'mission-vec-binary-machines-07-o2', 1, 'investigation', 'Which evidence shows the same raw value repeating across registers that should hold independent, physically unrelated readings?', '{"evidence":[{"id":"e1","label":"Register table","detail":"0x00 STATUS_MAIN = 0x0001; 0x02 CHANNEL_A_CAL = 0xDEAD; 0x04 CHANNEL_B_CAL = 0xDEAD; 0x06 MOTOR_LIMIT = 0x012C; 0x08 SENSOR_OFFSET = 0xDEAD; 0x0A FAULT_LOG = 0x0000"},{"id":"e2","label":"Tomas''s note","detail":"CHANNEL_A_CAL and CHANNEL_B_CAL calibrate two physically separate sensors and should almost never share an identical raw value"},{"id":"e3","label":"Byte''s note","detail":"MOTOR_LIMIT and FAULT_LOG both hold ordinary, plausible values for their labels"}],"question":"Which evidence shows the same raw value repeating across registers that should hold independent, physically unrelated readings?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),

  ('mission-vec-binary-machines-08-o1-c1', 'mission-vec-binary-machines-08-o1', 1, 'multiple_choice', 'Memory-mapped I/O means...', '{"question":"Memory-mapped I/O means...","options":[{"id":"a","text":"Registers require a special separate instruction set to access"},{"id":"b","text":"Registers occupy ordinary memory addresses, so reading or writing them uses the same operations as reading or writing memory"},{"id":"c","text":"Registers are stored only inside the CPU, never in memory"},{"id":"d","text":"Every register shares one single address"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-08-o2-c1', 'mission-vec-binary-machines-08-o2', 1, 'interactive_diagram', 'Order the steps of reading a memory-mapped register from address to value.', '{"diagramId":"mmio-access-path","hotspots":[{"id":"pick_address","label":"Choose the address","explanation":"Identify the register''s fixed, known address."},{"id":"issue_read","label":"Issue a read","explanation":"Request the value stored at that address."},{"id":"receive_value","label":"Receive the value","explanation":"The raw bits stored there come back."},{"id":"interpret","label":"Interpret the value","explanation":"Read the raw bits using the register''s known width and meaning."}],"task":"Order the steps from address to interpreted value."}'::jsonb, '{"correctOrderIds":["pick_address","issue_read","receive_value","interpret"]}'::jsonb),

  ('mission-vec-binary-machines-09-o1-c1', 'mission-vec-binary-machines-09-o1', 1, 'multiple_choice', 'Little-endian byte order means...', '{"question":"Little-endian byte order means...","options":[{"id":"a","text":"The least significant byte is stored or sent first"},{"id":"b","text":"The most significant byte is always stored first"},{"id":"c","text":"Bytes are sent in a random order"},{"id":"d","text":"Endianness only applies to text, not numbers"}]}'::jsonb, '{"correctOptionId":"a"}'::jsonb),
  ('mission-vec-binary-machines-09-o2-c1', 'mission-vec-binary-machines-09-o2', 1, 'browser_simulation', 'Two raw bytes arrive off this little-endian bus, in this order: 0xAD, then 0xDE. What is the actual 16-bit register value?', '{"screen":"MAINTENANCE BUS -- RAW BYTE CAPTURE -- CHANNEL_A_CAL","question":"Two raw bytes arrive off this little-endian bus, in this order: 0xAD, then 0xDE. What is the actual 16-bit register value?","records":[{"id":"r1","code":"0xADDE","detail":"Reading the bytes in the order they arrived, high byte first"},{"id":"r2","code":"0xDEAD","detail":"Applying little-endian order: the first byte received is the low byte, so it is placed second in the assembled value"},{"id":"r3","code":"0xAD00","detail":"Discarding the second byte entirely"},{"id":"r4","code":"0x00DE","detail":"Discarding the first byte entirely"}]}'::jsonb, '{"correctOptionId":"r2"}'::jsonb),

  ('mission-vec-binary-machines-10-o1-c1', 'mission-vec-binary-machines-10-o1', 1, 'multiple_choice', 'In two''s complement, a negative number is represented by...', '{"question":"In two''s complement, a negative number is represented by...","options":[{"id":"a","text":"Adding a minus sign character in front of the binary digits"},{"id":"b","text":"Setting the most significant bit to 1, with the magnitude found by inverting every bit and adding one"},{"id":"c","text":"Storing the number twice"},{"id":"d","text":"Two''s complement cannot represent negative numbers, only unsigned can"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-10-o2-c1', 'mission-vec-binary-machines-10-o2', 1, 'multiple_choice', 'The 16-bit value 0xFFFF, read as a signed two''s complement number, equals...', '{"question":"The 16-bit value 0xFFFF, read as a signed two''s complement number, equals...","options":[{"id":"a","text":"65535"},{"id":"b","text":"-1"},{"id":"c","text":"0"},{"id":"d","text":"32767"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-binary-machines-11-o1-c1', 'mission-vec-binary-machines-11-o1', 1, 'multiple_choice', 'When a 16-bit register overflows, the result is...', '{"question":"When a 16-bit register overflows, the result is...","options":[{"id":"a","text":"The register automatically expands to hold the extra bit"},{"id":"b","text":"The extra bit is discarded and the value wraps back around to 0x0000"},{"id":"c","text":"The board halts immediately"},{"id":"d","text":"The value is stored as a negative number automatically"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-11-o2-c1', 'mission-vec-binary-machines-11-o2', 1, 'multiple_choice', 'Overflow artifacts land at or near a register''s boundary values, 0x0000 or 0xFFFF. CHANNEL_A_CAL reads 0xDEAD. Is that consistent with an overflow artifact?', '{"question":"Overflow artifacts land at or near a register''s boundary values, 0x0000 or 0xFFFF. CHANNEL_A_CAL reads 0xDEAD. Is that consistent with an overflow artifact?","options":[{"id":"a","text":"Yes, any wrong-looking value is overflow"},{"id":"b","text":"No -- 0xDEAD sits nowhere near either boundary, so overflow does not explain it"},{"id":"c","text":"Only if the register is 8 bits instead of 16"},{"id":"d","text":"Cannot be determined"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),

  ('mission-vec-binary-machines-12-o1-c1', 'mission-vec-binary-machines-12-o1', 1, 'investigation', 'Which evidence proves 0xDEAD is a repeating pattern across unrelated registers, not one legitimate reading?', '{"evidence":[{"id":"e1","label":"Full register table","detail":"0x02 CHANNEL_A_CAL = 0xDEAD; 0x04 CHANNEL_B_CAL = 0xDEAD; 0x08 SENSOR_OFFSET = 0xDEAD; every other register holds a distinct, plausible value"},{"id":"e2","label":"Tomas''s note","detail":"CHANNEL_A_CAL, CHANNEL_B_CAL and SENSOR_OFFSET calibrate three physically separate sensors with no shared wiring"},{"id":"e3","label":"Byte''s note","detail":"MOTOR_LIMIT alone holds 0x012C, an ordinary configured value"}],"question":"Which evidence proves 0xDEAD is a repeating pattern across unrelated registers, not one legitimate reading?"}'::jsonb, '{"requiredEvidenceIds":["e1"]}'::jsonb),
  ('mission-vec-binary-machines-12-o2-c1', 'mission-vec-binary-machines-12-o2', 1, 'multiple_choice', 'This bus is documented as little-endian. Read big-endian by mistake, the two raw bytes would assemble into 0xADDE instead. Checking the board''s documented status and fault code table, which of these is true?', '{"question":"This bus is documented as little-endian. Read big-endian by mistake, the two raw bytes would assemble into 0xADDE instead. Checking the board''s documented status and fault code table, which of these is true?","options":[{"id":"a","text":"0xADDE appears in the documented code table, so it is just a misread"},{"id":"b","text":"Neither 0xDEAD nor 0xADDE appears anywhere in the board''s documented status or fault code table -- the value is not explained by an endianness mistake in either direction"},{"id":"c","text":"Endianness cannot affect a status code, only sensor data"},{"id":"d","text":"The documented table does not exist for this board"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-12-o3-c1', 'mission-vec-binary-machines-12-o3', 1, 'multiple_choice', '0xDEAD sits nowhere near the 16-bit boundary values 0x0000 or 0xFFFF, and reading it as signed two''s complement gives an ordinary negative number with no special meaning in this board''s documentation. What does that rule out?', '{"question":"0xDEAD sits nowhere near the 16-bit boundary values 0x0000 or 0xFFFF, and reading it as signed two''s complement gives an ordinary negative number with no special meaning in this board''s documentation. What does that rule out?","options":[{"id":"a","text":"It rules out nothing, the value is still unexplained"},{"id":"b","text":"It rules out both overflow and a legitimate signed sensor reading as explanations, leaving no ordinary data-path explanation for the value"},{"id":"c","text":"It proves the value is a deliberate fault code"},{"id":"d","text":"It proves the register is broken hardware"}]}'::jsonb, '{"correctOptionId":"b"}'::jsonb),
  ('mission-vec-binary-machines-12-o4-c1', 'mission-vec-binary-machines-12-o4', 1, 'boss_encounter', 'Having proven the pattern, ruled out a misread, and ruled out real data, state what 0xDEAD actually is and what it implies about how this board was originally commissioned.', '{"stages":[{"objectiveRef":"mission-vec-binary-machines-12-o1","label":"Prove the pattern"},{"objectiveRef":"mission-vec-binary-machines-12-o2","label":"Rule out a misread"},{"objectiveRef":"mission-vec-binary-machines-12-o3","label":"Rule out real data"}],"task":"State the finding in one sentence: 0xDEAD is not a fault code but a placeholder value the original engineers left in three unrelated calibration and offset registers, meaning roughly \"not finished configuring this\" -- never revisited before the board was sealed into the wall, decades ago, still mid-commissioning."}'::jsonb, '{"requiredObjectiveIds":["mission-vec-binary-machines-12-o1","mission-vec-binary-machines-12-o2","mission-vec-binary-machines-12-o3"],"allCorrect":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-vec-binary-machines-01-o1-c1', 'orientation', 'Ask whether hexadecimal is a new kind of number, or just a shorter way of writing binary.', 10, 1),
  ('mission-vec-binary-machines-01-o1-c1', 'concept', 'Sixteen symbols in hex, two symbols in binary -- and every hex digit lines up with exactly four binary digits.', 20, 2),
  ('mission-vec-binary-machines-01-o1-c1', 'solution', 'e2 is the answer: each hex digit maps to exactly four binary digits, so hex is a direct shorthand for binary, nothing more.', 30, 3),
  ('mission-vec-binary-machines-01-o2-c1', 'orientation', 'Split the 16 bits into four groups of four, then convert each group on its own.', 10, 1),
  ('mission-vec-binary-machines-01-o2-c1', 'solution', '1101 = D, 1110 = E, 1010 = A, 1101 = D, giving 0xDEAD.', 20, 2),

  ('mission-vec-binary-machines-02-o1-c1', 'orientation', 'Start from the smallest unit and work up: bit, then byte, then word.', 10, 1),
  ('mission-vec-binary-machines-02-o1-c1', 'solution', 'A bit is one binary digit, a byte is 8 bits, and this board''s word is 16 bits -- 2 bytes.', 20, 2),
  ('mission-vec-binary-machines-02-o2-c1', 'orientation', 'Two hex digits make one byte, so four hex digits make how many bytes?', 10, 1),
  ('mission-vec-binary-machines-02-o2-c1', 'solution', '0xDE is the high byte and 0xAD is the low byte -- 2 bytes total, forming one 16-bit word.', 20, 2),

  ('mission-vec-binary-machines-03-o1-c1', 'orientation', 'Boolean logic only ever deals with two possible values.', 10, 1),
  ('mission-vec-binary-machines-03-o1-c1', 'solution', 'Boolean logic operates on exactly true and false, combined by fixed rules -- nothing else.', 20, 2),
  ('mission-vec-binary-machines-03-o2-c1', 'orientation', 'A bit reading 1 and a correct statement share the same underlying value.', 10, 1),
  ('mission-vec-binary-machines-03-o2-c1', 'solution', 'True: the bit reading 1, and the correct statement. False: the bit reading 0, and the incorrect statement.', 20, 2),

  ('mission-vec-binary-machines-04-o1-c1', 'orientation', 'Ask how many true inputs each operator needs before it outputs true.', 10, 1),
  ('mission-vec-binary-machines-04-o1-c1', 'solution', 'AND needs both true. OR needs at least one true. NOT flips a single value. XOR needs the two inputs to differ.', 20, 2),
  ('mission-vec-binary-machines-04-o2-c1', 'orientation', 'XOR is true only when its two inputs are different from each other.', 10, 1),
  ('mission-vec-binary-machines-04-o2-c1', 'solution', '1 and 1 are the same value, so XOR outputs 0.', 20, 2),

  ('mission-vec-binary-machines-05-o1-c1', 'orientation', 'Count in binary from 00 up to 11 -- that is the natural order of the rows.', 10, 1),
  ('mission-vec-binary-machines-05-o1-c1', 'solution', '00, then 01, then 10, then 11 -- the four rows in binary counting order.', 20, 2),
  ('mission-vec-binary-machines-05-o2-c1', 'orientation', 'AND only ever produces true on one single row of its truth table.', 10, 1),
  ('mission-vec-binary-machines-05-o2-c1', 'solution', 'AND outputs 1 only on the 1,1 row -- both inputs true.', 20, 2),

  ('mission-vec-binary-machines-06-o1-c1', 'orientation', 'AND keeps a bit only where both inputs have a 1 in that position.', 10, 1),
  ('mission-vec-binary-machines-06-o1-c1', 'solution', 'The upper nibble is masked to zero by the 0000 half, and the lower nibble passes through unchanged: 0000 1010.', 20, 2),
  ('mission-vec-binary-machines-06-o2-c1', 'orientation', 'Look for the evidence that explains the masking technique itself, not just the raw byte.', 10, 1),
  ('mission-vec-binary-machines-06-o2-c1', 'solution', 'e2: masking with 0000 0001 via AND isolates only the lowest bit, the ONLINE flag, leaving every other bit untouched.', 20, 2),

  ('mission-vec-binary-machines-07-o1-c1', 'orientation', 'A register is not a file, a gate, or a protocol -- it is a storage location.', 10, 1),
  ('mission-vec-binary-machines-07-o1-c1', 'solution', 'A register is a fixed-width, named, addressed storage location holding one value at a time.', 20, 2),
  ('mission-vec-binary-machines-07-o2-c1', 'orientation', 'Scan the whole table for a value that shows up more than once.', 10, 1),
  ('mission-vec-binary-machines-07-o2-c1', 'solution', 'e1: 0xDEAD appears at CHANNEL_A_CAL, CHANNEL_B_CAL and SENSOR_OFFSET -- three separate registers, one repeated value.', 20, 2),

  ('mission-vec-binary-machines-08-o1-c1', 'orientation', 'Ask whether registers need a special access method, or whether they behave like ordinary memory.', 10, 1),
  ('mission-vec-binary-machines-08-o1-c1', 'solution', 'Memory-mapped registers sit at ordinary memory addresses, so reading or writing them is just a normal memory operation.', 20, 2),
  ('mission-vec-binary-machines-08-o2-c1', 'orientation', 'You cannot interpret a value before you have actually received it.', 10, 1),
  ('mission-vec-binary-machines-08-o2-c1', 'solution', 'Choose the address, issue the read, receive the value, then interpret it -- in that order.', 20, 2),

  ('mission-vec-binary-machines-09-o1-c1', 'orientation', 'Little-endian and "least significant" go together.', 10, 1),
  ('mission-vec-binary-machines-09-o1-c1', 'solution', 'Little-endian sends the least significant byte first.', 20, 2),
  ('mission-vec-binary-machines-09-o2-c1', 'orientation', 'If the low byte arrives first, it belongs at the low end of the assembled value, not the high end.', 10, 1),
  ('mission-vec-binary-machines-09-o2-c1', 'solution', 'r2: 0xAD is the low byte and arrived first, 0xDE is the high byte and arrived second -- assembled correctly, that is 0xDEAD.', 20, 2),

  ('mission-vec-binary-machines-10-o1-c1', 'orientation', 'Two''s complement uses one specific bit to signal negative, not a separate symbol.', 10, 1),
  ('mission-vec-binary-machines-10-o1-c1', 'solution', 'The most significant bit set to 1 means negative, with the magnitude found by inverting every bit and adding one.', 20, 2),
  ('mission-vec-binary-machines-10-o2-c1', 'orientation', 'All bits set to 1, in two''s complement, is the smallest possible negative magnitude.', 10, 1),
  ('mission-vec-binary-machines-10-o2-c1', 'solution', '0xFFFF as signed two''s complement equals -1.', 20, 2),

  ('mission-vec-binary-machines-11-o1-c1', 'orientation', 'Nothing on a fixed-width register can hold a value outside its bit width -- the extra has to go somewhere.', 10, 1),
  ('mission-vec-binary-machines-11-o1-c1', 'solution', 'The extra bit is simply discarded, wrapping the value back around to 0x0000.', 20, 2),
  ('mission-vec-binary-machines-11-o2-c1', 'orientation', 'Compare 0xDEAD directly against 0x0000 and 0xFFFF -- is it close to either one?', 10, 1),
  ('mission-vec-binary-machines-11-o2-c1', 'solution', '0xDEAD is nowhere near either boundary, so overflow does not explain it.', 20, 2),

  ('mission-vec-binary-machines-12-o1-c1', 'orientation', 'You have seen this table before -- look for the value that shows up more than once.', 10, 1),
  ('mission-vec-binary-machines-12-o1-c1', 'solution', 'e1: 0xDEAD recurs at three separate, physically unrelated registers -- CHANNEL_A_CAL, CHANNEL_B_CAL and SENSOR_OFFSET.', 20, 2),
  ('mission-vec-binary-machines-12-o2-c1', 'orientation', 'Check both possible byte orderings against the documented code table, not just the one you expect.', 10, 1),
  ('mission-vec-binary-machines-12-o2-c1', 'solution', 'Neither 0xDEAD nor its reversed reading 0xADDE appears anywhere in the documented table -- an endianness mistake does not explain it either way.', 20, 2),
  ('mission-vec-binary-machines-12-o3-c1', 'orientation', 'Test both remaining ordinary explanations -- overflow, and a legitimate signed reading -- against the actual value.', 10, 1),
  ('mission-vec-binary-machines-12-o3-c1', 'solution', '0xDEAD is nowhere near an overflow boundary, and its signed value has no documented meaning -- both ordinary explanations are ruled out.', 20, 2),
  ('mission-vec-binary-machines-12-o4-c1', 'orientation', 'Look at what all three proofs eliminated together, not at any one of them alone.', 15, 1),
  ('mission-vec-binary-machines-12-o4-c1', 'solution', '0xDEAD is a placeholder the original engineers left behind in three unrelated registers, meaning roughly "not finished configuring this" -- never revisited before the board was sealed into the wall, decades ago, mid-commissioning.', 25, 2);
